// Extrait le message WhatsApp depuis le payload Meta Cloud API
const body = $input.first().json.body;

const entry = body.entry?.[0];
const change = entry?.changes?.[0];
const value = change?.value;

// Ignorer les events de statut (delivered/read), on ne traite que les vrais messages entrants
if (!value?.messages || value.messages.length === 0) {
  return [{ json: { skip: true, reason: 'no_message_or_status_event' } }];
}

const message = value.messages[0];
const contact = value.contacts?.[0];

const from = message.from; // numero WhatsApp au format international sans +
const messageId = message.id;
const timestamp = message.timestamp;
const type = message.type;

let text = '';
let interactiveId = null;

if (type === 'text') {
  text = message.text?.body?.trim() || '';
} else if (type === 'interactive') {
  if (message.interactive?.type === 'button_reply') {
    interactiveId = message.interactive.button_reply.id;
    text = message.interactive.button_reply.title;
  } else if (message.interactive?.type === 'list_reply') {
    interactiveId = message.interactive.list_reply.id;
    text = message.interactive.list_reply.title;
  }
} else if (type === 'image') {
  // recherche par image, traite plus tard si besoin
  text = '__IMAGE__';
} else {
  text = '__UNSUPPORTED__';
}

return [{
  json: {
    skip: false,
    from: '+' + from,
    fromRaw: from,
    messageId,
    timestamp,
    type,
    text,
    interactiveId,
    contactName: contact?.profile?.name || null
  }
}];

// Machine a etats de la conversation de commande
// Etats possibles : START, CHOIX_CATEGORIE, CHOIX_PRODUIT, QUANTITE, ADRESSE, RECAP, PAIEMENT, TERMINE

const msg = $('Parser le message WhatsApp').first().json;
const convResponse = $input.first().json;

// Si la conversation n'existe pas encore (404) ou est vide, on demarre a START
let state = convResponse?.state || 'START';
let cart = convResponse?.cart || [];
let currentCategory = convResponse?.currentCategory || null;
let currentProduct = convResponse?.currentProduct || null;
let deliveryAddress = convResponse?.deliveryAddress || null;
let deliveryZoneId = convResponse?.deliveryZoneId || null;

const text = (msg.text || '').toLowerCase().trim();
const interactiveId = msg.interactiveId;

// Commande de reinitialisation a tout moment
if (text === 'annuler' || text === 'recommencer' || text === '0') {
  return [{
    json: {
      from: msg.fromRaw,
      newState: 'CHOIX_CATEGORIE',
      cart: [],
      currentCategory: null,
      currentProduct: null,
      deliveryAddress: null,
      deliveryZoneId: null,
      action: 'SHOW_CATEGORIES',
      replyText: 'Commande annulee. On recommence ! Choisissez une categorie :'
    }
  }];
}

let action = 'REPLY_TEXT';
let replyText = '';
let newState = state;

switch (state) {
  case 'START':
    newState = 'CHOIX_CATEGORIE';
    action = 'SHOW_CATEGORIES';
    replyText = 'Bienvenue chez CCB Materiaux ! Que cherchez-vous aujourd hui ?';
    break;

  case 'CHOIX_CATEGORIE':
    if (interactiveId && interactiveId.startsWith('cat_')) {
      currentCategory = interactiveId.replace('cat_', '');
      newState = 'CHOIX_PRODUIT';
      action = 'SHOW_PRODUCTS';
      replyText = 'Voici nos produits dans cette categorie :';
    } else {
      action = 'SHOW_CATEGORIES';
      replyText = 'Merci de choisir une categorie dans la liste ci-dessous :';
    }
    break;

  case 'CHOIX_PRODUIT':
    if (interactiveId && interactiveId.startsWith('prod_')) {
      currentProduct = interactiveId.replace('prod_', '');
      newState = 'QUANTITE';
      action = 'ASK_QUANTITY';
      replyText = 'Combien en voulez-vous ? (indiquez juste le nombre, ex: 5)';
    } else {
      action = 'SHOW_PRODUCTS';
      replyText = 'Merci de choisir un produit dans la liste.';
    }
    break;

  case 'QUANTITE': {
    const qty = parseInt(text.replace(/[^0-9]/g, ''), 10);
    if (!qty || qty <= 0) {
      action = 'REPLY_TEXT';
      replyText = 'Merci d indiquer une quantite valide (nombre entier superieur a 0).';
    } else {
      cart.push({ productId: currentProduct, quantity: qty });
      currentProduct = null;
      newState = 'AJOUTER_OU_CONTINUER';
      action = 'ASK_ADD_MORE';
      replyText = 'Ajoute au panier. Voulez-vous ajouter un autre produit ou continuer la commande ?';
    }
    break;
  }

  case 'AJOUTER_OU_CONTINUER':
    if (interactiveId === 'add_more') {
      newState = 'CHOIX_CATEGORIE';
      action = 'SHOW_CATEGORIES';
      replyText = 'Choisissez une autre categorie :';
    } else if (interactiveId === 'continue_order') {
      newState = 'ADRESSE';
      action = 'ASK_ADDRESS';
      replyText = 'Quelle est votre adresse de livraison ? (quartier + ville)';
    } else {
      action = 'ASK_ADD_MORE';
      replyText = 'Merci de choisir une option : ajouter un produit ou continuer.';
    }
    break;

  case 'ADRESSE':
    if (text.length < 3) {
      action = 'ASK_ADDRESS';
      replyText = 'Merci d indiquer une adresse plus precise (quartier + ville).';
    } else {
      deliveryAddress = msg.text;
      newState = 'CHOIX_ZONE';
      action = 'SHOW_DELIVERY_ZONES';
      replyText = 'Merci. Selectionnez votre zone de livraison pour calculer les frais :';
    }
    break;

  case 'CHOIX_ZONE':
    if (interactiveId && interactiveId.startsWith('zone_')) {
      deliveryZoneId = interactiveId.replace('zone_', '');
      newState = 'RECAP';
      action = 'SHOW_RECAP';
      replyText = 'Voici le recapitulatif de votre commande :';
    } else {
      action = 'SHOW_DELIVERY_ZONES';
      replyText = 'Merci de choisir une zone dans la liste.';
    }
    break;

  case 'RECAP':
    if (interactiveId === 'confirm_order') {
      newState = 'CHOIX_PAIEMENT';
      action = 'SHOW_PAYMENT_OPTIONS';
      replyText = 'Comment souhaitez-vous payer ?';
    } else if (interactiveId === 'cancel_order') {
      newState = 'CHOIX_CATEGORIE';
      cart = [];
      action = 'SHOW_CATEGORIES';
      replyText = 'Commande annulee. Recommencons :';
    } else {
      action = 'SHOW_RECAP';
      replyText = 'Merci de confirmer ou annuler la commande.';
    }
    break;

  case 'CHOIX_PAIEMENT':
    if (interactiveId === 'pay_wave' || interactiveId === 'pay_orange_money' || interactiveId === 'pay_livraison') {
      newState = 'TERMINE';
      action = 'CREATE_ORDER';
      replyText = 'Commande enregistree ! Vous allez recevoir la confirmation.';
    } else {
      action = 'SHOW_PAYMENT_OPTIONS';
      replyText = 'Merci de choisir un mode de paiement dans la liste.';
    }
    break;

  case 'TERMINE':
    newState = 'CHOIX_CATEGORIE';
    cart = [];
    action = 'SHOW_CATEGORIES';
    replyText = 'Souhaitez-vous passer une nouvelle commande ? Choisissez une categorie :';
    break;

  default:
    newState = 'CHOIX_CATEGORIE';
    action = 'SHOW_CATEGORIES';
    replyText = 'Bienvenue chez CCB Materiaux ! Que cherchez-vous ?';
}

return [{
  json: {
    from: msg.fromRaw,
    newState,
    cart,
    currentCategory,
    currentProduct,
    deliveryAddress,
    deliveryZoneId,
    paymentMethod: interactiveId && interactiveId.startsWith('pay_') ? interactiveId.replace('pay_', '') : (convResponse?.paymentMethod || null),
    action,
    replyText
  }
}];

// Construit le payload WhatsApp selon le type de reponse attendu (texte simple, boutons, ou liste)
const state = $('Machine a etats conversation').first().json;
const action = state.action;
const to = state.from;

let payload;

if (action === 'SHOW_CATEGORIES') {
  const categories = ['Gros oeuvre', 'Etancheite', 'Carrelage', 'Plomberie', 'Electricite', 'Sanitaires', 'Electromenager', 'Solaire'];
  payload = {
    messaging_product: 'whatsapp',
    to,
    type: 'interactive',
    interactive: {
      type: 'list',
      header: { type: 'text', text: 'CCB Materiaux' },
      body: { text: state.replyText },
      action: {
        button: 'Voir les categories',
        sections: [{
          title: 'Categories',
          rows: categories.map((c, i) => ({ id: 'cat_' + c.toLowerCase().replace(/ /g, '_'), title: c.substring(0, 24) }))
        }]
      }
    }
  };
} else if (action === 'SHOW_PRODUCTS') {
  const products = ($input.first().json.body || []).slice(0, 10);
  payload = {
    messaging_product: 'whatsapp',
    to,
    type: 'interactive',
    interactive: {
      type: 'list',
      body: { text: state.replyText },
      action: {
        button: 'Voir les produits',
        sections: [{
          title: 'Produits',
          rows: products.map(p => ({ id: 'prod_' + p.id, title: p.name.substring(0, 24), description: (p.price + ' FCFA').substring(0, 72) }))
        }]
      }
    }
  };
} else if (action === 'SHOW_DELIVERY_ZONES') {
  const zones = ($input.first().json.body || []).slice(0, 10);
  payload = {
    messaging_product: 'whatsapp',
    to,
    type: 'interactive',
    interactive: {
      type: 'list',
      body: { text: state.replyText },
      action: {
        button: 'Choisir une zone',
        sections: [{
          title: 'Zones de livraison',
          rows: zones.map(z => ({ id: 'zone_' + z.id, title: z.name.substring(0, 24), description: (z.fee + ' FCFA').substring(0, 72) }))
        }]
      }
    }
  };
} else if (action === 'SHOW_RECAP') {
  payload = {
    messaging_product: 'whatsapp',
    to,
    type: 'interactive',
    interactive: {
      type: 'button',
      body: { text: state.replyText + '\n\nAdresse : ' + state.deliveryAddress },
      action: {
        buttons: [
          { type: 'reply', reply: { id: 'confirm_order', title: 'Confirmer' } },
          { type: 'reply', reply: { id: 'cancel_order', title: 'Annuler' } }
        ]
      }
    }
  };
} else if (action === 'SHOW_PAYMENT_OPTIONS') {
  payload = {
    messaging_product: 'whatsapp',
    to,
    type: 'interactive',
    interactive: {
      type: 'button',
      body: { text: state.replyText },
      action: {
        buttons: [
          { type: 'reply', reply: { id: 'pay_wave', title: 'Wave' } },
          { type: 'reply', reply: { id: 'pay_orange_money', title: 'Orange Money' } },
          { type: 'reply', reply: { id: 'pay_livraison', title: 'A la livraison' } }
        ]
      }
    }
  };
} else {
  // ASK_QUANTITY, ASK_ADD_MORE (variante texte), ASK_ADDRESS, REPLY_TEXT, ou apres creation commande
  if (action === 'ASK_ADD_MORE') {
    payload = {
      messaging_product: 'whatsapp',
      to,
      type: 'interactive',
      interactive: {
        type: 'button',
        body: { text: state.replyText },
        action: {
          buttons: [
            { type: 'reply', reply: { id: 'add_more', title: 'Ajouter un produit' } },
            { type: 'reply', reply: { id: 'continue_order', title: 'Continuer' } }
          ]
        }
      }
    };
  } else {
    payload = {
      messaging_product: 'whatsapp',
      to,
      type: 'text',
      text: { body: state.replyText }
    };
  }
}

return [{ json: payload }];

// Apres creation de la commande, prepare un message de confirmation avec le numero de commande
const order = $input.first().json;
const state = $('Machine a etats conversation').first().json;

const orderNumber = order.orderNumber || order.id || 'N/A';
const total = order.total || '';

return [{
  json: {
    messaging_product: 'whatsapp',
    to: state.from,
    type: 'text',
    text: {
      body: 'Merci pour votre commande CCB Materiaux !\n\nNumero de commande : ' + orderNumber + (total ? ('\nTotal : ' + total + ' FCFA') : '') + '\n\nNotre equipe va vous contacter sous peu pour confirmer la livraison.'
    }
  }
}];
